  array[$cv$A modern web browser$cv$, $cv$A code editor to customise the files$cv$, $cv$Any static web host (no build step, no server-side code)$cv$, $cv$A form backend or form service if you want contact forms to send messages$cv$]::text[],
  array[$cv$Written for current versions of Chrome, Edge, Firefox and Safari$cv$, $cv$HTML validated with html-validate (recommended rules): 0 errors on all 10 HTML pages$cv$, $cv$All JavaScript passes a syntax check; no external CDNs, fonts or tracking$cv$, $cv$Business, service and portfolio kits rendered in headless Chrome at 320–1440px with no horizontal scrolling$cv$]::text[],
  $cv$[{"question":"Is this the same as buying the four kits separately?","answer":"Yes — the collection contains the same files as the individual Business, Service Business, Portfolio and SaaS Landing Page kits, in one download and under one licence."},{"question":"Do I need to know a framework?","answer":"No. The kits are plain HTML, CSS and JavaScript. Basic HTML/CSS knowledge is enough to customise them."},{"question":"Will the contact forms send email?","answer":"Not on their own. Forms validate input in the browser; connect them to a form service or your own server as described in each README."}]$cv$::jsonb,
